import React from 'react';

import { InnovationPortfolio, TotalInnovationPerformance } from './components';
import { useInnovationHubOverviewPageData } from './hooks/useInnovationHubOverviewPageData';
import { StyledOverviewRoot } from './Overview.styles';

interface OverviewProps {
  dataTestId?: string;
}

export const Overview: React.FC<OverviewProps> = ({ dataTestId }) => {
  const pageData = useInnovationHubOverviewPageData();

  const containerDataTestId = dataTestId
    ? `${dataTestId}-container`
    : 'innovation-hub-overview-container';

  return (
    <StyledOverviewRoot
      data-testid={containerDataTestId}
      data-full-width="true"
    >
      <TotalInnovationPerformance
        dataTestId={
          dataTestId
            ? `${dataTestId}-total-innovation-performance`
            : 'innovation-hub-overview-total-innovation-performance'
        }
        totalPerformanceData={pageData.totalPerformance}
      />
      <InnovationPortfolio
        dataTestId={
          dataTestId
            ? `${dataTestId}-portfolio`
            : 'innovation-hub-overview-portfolio'
        }
        portfolioData={pageData.portfolio}
      />
    </StyledOverviewRoot>
  );
};
